-- New Hero WODs batch 4b: 12 official CrossFit Hero workouts (crossfit.com/benchmark/<name>).
-- Generated by gen_new4b.py. Not yet run.
do $$
declare n int;
begin
  if exists (select 1 from benchmark_workouts where slug in ('jorge', 'josh-o', 'josie', 'justin', 'k27', 'kelly-brown', 'kerrie', 'kev', 'kevin', 'laura', 'ledesma', 'lee')) then raise exception 'slug exists'; end if;
  insert into benchmark_workouts (name, slug, category, subcategory, format, scheme, duration_estimate, difficulty, body_focus, equipment, scoring_type, description, movements, scoring_notes, tips, coaching_tips, scaling_notes, faqs, youtube_url) values
  ('Jorge',
   'jorge',
   'hero',
   null,
   'For Time',
   'For Time',
   '15–25 min',
   'advanced',
   'full-body',
   array['ghd','barbell']::text[],
   'time',
   'Jorge honors U.S. Coast Guard Chief Petty Officer Fernando Jorge, 39, of Cypress, California, an Aviation Survival Technician Chief. He died on Feb. 28, 2012, when his unit''s helicopter crashed into Mobile Bay during a training mission.

You alternate GHD sit-ups and squat cleans (155 lb / 105 lb) down two ladders: 30 sit-ups and 15 cleans, then 24 and 12, 18 and 9, 12 and 6, and finally 6 and 3. That adds up to 90 GHD sit-ups and 45 squat cleans. The first pairs are the hardest, because the big sit-up sets tire your trunk right before the heaviest clean sets. The sets shrink as you go, so a steady start pays off at the end.',
   '[{"name": "GHD Sit-Ups", "reps": "30-24-18-12-6", "tip": "Sit back until your hands reach toward the floor, then use your hips and legs to snap up. Do the set before each round of cleans."}, {"name": "Squat Cleans", "reps": "15-12-9-6-3", "tip": "Catch the bar in a full front squat and stand tall. Quick singles are fine on the big sets.", "rx_men": "155 lb", "rx_women": "105 lb"}]'::jsonb,
   'Record your finish time.',
   '["Do not sprint the first set of 30 GHD sit-ups", "Break the 15 cleans before your back rounds", "The ladders get shorter, so save energy for the finish"]'::jsonb,
   '["If you are new to the GHD, do a few practice reps on another day first, because 90 reps is a lot of volume.", "Keep your GHD reps smooth and controlled rather than throwing your head back hard.", "On the squat cleans, set a flat back before every pull and keep the bar close.", "Plan the first set of 15 cleans as small sets, such as 5, 5 and 5.", "Walk to the bar after each GHD set and take one breath before your first clean."]'::jsonb,
   'Replace the GHD sit-ups with AbMat sit-ups, or cut each set in half. Lower the barbell to 115 lb / 75 lb or less, or use power cleans plus a front squat if the full squat clean is not there yet. Newer athletes can halve every number in both ladders.',
   '[{"question": "What is the Jorge workout?", "answer": "For time: 30 GHD sit-ups, 15 squat cleans, 24 GHD sit-ups, 12 squat cleans, 18 GHD sit-ups, 9 squat cleans, 12 GHD sit-ups, 6 squat cleans, 6 GHD sit-ups and 3 squat cleans. The barbell is 155 lb / 105 lb."}, {"question": "How many total reps are in Jorge?", "answer": "135 reps: 90 GHD sit-ups and 45 squat cleans."}, {"question": "Who was Jorge?", "answer": "U.S. Coast Guard Chief Petty Officer Fernando Jorge, 39, of Cypress, California, an Aviation Survival Technician Chief. He died on Feb. 28, 2012, when his unit''s helicopter crashed into Mobile Bay during a training mission."}, {"question": "What if I do not have a GHD?", "answer": "Do AbMat sit-ups instead. They are easier per rep, so note the change with your time."}]'::jsonb,
   'https://www.youtube.com/watch?v=rAdIkjd_ETo'),
  ('Josh-O',
   'josh-o',
   'hero',
   null,
   'For Time',
   'For Time (Partner)',
   '35–50 min',
   'intermediate',
   'full-body',
   array['dumbbells','rower','running']::text[],
   'time',
   'Josh-O honors Josh Owen, 44, a Deputy Sheriff for Pope County in Minnesota. He died on April 15, 2023, from injuries sustained while handling a domestic violence call. He served in the Army National Guard and later as a Chief of Police and Deputy Sheriff, and was a member of the Pope County SWAT team.

You do this one with a partner and a pair of dumbbells (50 lb / 35 lb). You run 400 m together, then split 2 rounds of 44 dumbbell front squats, 44 floor presses and 44 hang clean and jerks. Next comes a 1,979 m row, then 2 rounds of 44 deadlifts, 44 bent-over rows and 44 lunges, and a last 400 m run together. Splitting the work as you like means smart swaps decide your time.',
   '[{"name": "Run", "reps": "400 m together", "tip": "Run side by side. Keep it easy, because the dumbbell work is long."}, {"name": "Dumbbell Front Squats", "reps": "2 rounds of 44", "tip": "Rest the dumbbells on your shoulders, elbows up, and squat below parallel.", "rx_men": "50 lb", "rx_women": "35 lb"}, {"name": "Dumbbell Floor Presses", "reps": "2 rounds of 44", "tip": "Lie on the floor, lower until your upper arms touch it, then press to lockout.", "rx_men": "50 lb", "rx_women": "35 lb"}, {"name": "Dumbbell Hang Clean and Jerks", "reps": "2 rounds of 44", "tip": "From the hang, clean both dumbbells to your shoulders, then dip and drive them overhead.", "rx_men": "50 lb", "rx_women": "35 lb"}, {"name": "Row", "reps": "1,979 m", "tip": "Split the distance between you. Short turns keep the pace high."}, {"name": "Dumbbell Deadlifts", "reps": "2 rounds of 44", "tip": "Flat back, dumbbells at your sides, stand all the way up.", "rx_men": "50 lb", "rx_women": "35 lb"}, {"name": "Dumbbell Bent-Over Rows", "reps": "2 rounds of 44", "tip": "Hinge forward with a flat back and pull both dumbbells to your ribs.", "rx_men": "50 lb", "rx_women": "35 lb"}, {"name": "Dumbbell Lunges", "reps": "2 rounds of 44", "tip": "Back knee kisses the floor and you stand tall each rep.", "rx_men": "50 lb", "rx_women": "35 lb"}, {"name": "Run", "reps": "400 m together", "tip": "The last effort. Finish together."}]'::jsonb,
   'Record your team''s finish time.',
   '["Swap often, before either of you slows down", "Run together, split everything else", "Decide how you will count lunges before you start"]'::jsonb,
   '["Agree on a set size for each movement, such as 11 reps each, and swap without talking it over.", "Keep the dumbbells close to the working partner so swaps take seconds.", "On the floor press, keep your wrists stacked over your elbows and pause lightly at the bottom.", "Split the row into short turns of 200 to 300 m so both of you stay fresh.", "On the bent-over rows, keep your chest still and pull with your back, not by standing up."]'::jsonb,
   'Use lighter dumbbells, such as 35 lb / 20 lb. Cut each set to 30 reps, or do 1 round of each set of dumbbell movements instead of 2. Shorten the row to 1,000 m if time is a concern.',
   '[{"question": "What is the Josh-O workout?", "answer": "A partner workout for time: run 400 m together, then 2 rounds of 44 dumbbell front squats, 44 floor presses and 44 hang clean and jerks, a 1,979 m row, 2 rounds of 44 deadlifts, 44 bent-over rows and 44 lunges, then run 400 m together. The dumbbells are 50 lb / 35 lb."}, {"question": "How do partners split Josh-O?", "answer": "Both partners run together. All other work, including the row, can be split however you like."}, {"question": "How many dumbbells do I need?", "answer": "CrossFit says to use two dumbbells, so you need one pair for the team. It does not say whether each partner needs their own pair."}, {"question": "Are the 44 lunges counted per leg?", "answer": "CrossFit does not say. Count each step as one rep, or 44 per leg, and note which one you chose with your time."}, {"question": "Who was Josh-O?", "answer": "Josh Owen, 44, a Deputy Sheriff for Pope County, Minnesota, and an Army National Guard veteran. He died on April 15, 2023, from injuries sustained while handling a domestic violence call."}]'::jsonb,
   null),
  ('Josie',
   'josie',
   'hero',
   null,
   'For Time',
   'For Time',
   '30–45 min',
   'advanced',
   'full-body',
   array['running','barbell','weightedVest','bodyweight']::text[],
   'time',
   'Josie honors Deputy U.S. Marshal Josie Wells, 27, of Harleston, Mississippi, who was killed in the line of duty on March 10, 2015. He joined the Marshals Service in 2011, and he enjoyed CrossFit workouts with friends and colleagues, especially ones with running or power cleans.

You wear a 20 lb vest and start with a 1 mile run. Then you do 3 rounds of 30 burpees, 4 power cleans and 6 front squats (155 lb / 105 lb), and finish with another 1 mile run. CrossFit lists the vest as part of the Rx without limiting it to the runs, so wear it the whole way. The 90 burpees in the vest wear down your legs before the last mile.',
   '[{"name": "Run", "reps": "1 mile", "tip": "Settle into a pace you can hold. The vest makes it easy to start too fast.", "rx_men": "20 lb vest", "rx_women": "20 lb vest"}, {"name": "Burpees", "reps": "3 rounds of 30", "tip": "Chest to the floor and a small jump at the top. Find a steady rhythm.", "rx_men": "20 lb vest", "rx_women": "20 lb vest"}, {"name": "Power Cleans", "reps": "3 rounds of 4", "tip": "Catch the bar above parallel. Take them as quick singles.", "rx_men": "155 lb", "rx_women": "105 lb"}, {"name": "Front Squats", "reps": "3 rounds of 6", "tip": "Clean the bar to your shoulders, elbows up, and squat below parallel.", "rx_men": "155 lb", "rx_women": "105 lb"}, {"name": "Run", "reps": "1 mile", "tip": "Tired legs from the burpees. Shorten your stride and keep moving.", "rx_men": "20 lb vest", "rx_women": "20 lb vest"}]'::jsonb,
   'Record your finish time.',
   '["Run the first mile at a pace you could hold for both", "Pace the 30 burpees, do not race them", "Wear the vest the whole way"]'::jsonb,
   '["Strap the vest tight and high so it does not bounce on the runs.", "Break the 30 burpees into sets of 10 with a breath between them.", "Clean the bar for the front squats from the floor after the last power clean, so the barbell work flows as one set.", "Keep your elbows high on the front squats so the bar stays on your shoulders.", "Start the last mile slowly and build the pace once your legs come back."]'::jsonb,
   'Go without the vest or use a lighter one. Lower the barbell to 115 lb / 75 lb or less. Shorten each run to 800 m and cut the burpees to 20 per round.',
   '[{"question": "What is the Josie workout?", "answer": "For time, in a 20 lb vest: 1 mile run, then 3 rounds of 30 burpees, 4 power cleans and 6 front squats (155 lb / 105 lb), then a 1 mile run."}, {"question": "How many total reps are in Josie?", "answer": "120 reps: 90 burpees, 12 power cleans and 18 front squats, plus 2 miles of running."}, {"question": "Do I wear the vest for the whole workout?", "answer": "CrossFit lists the 20 lb vest as part of the Rx and does not limit it to the runs, so wear it throughout."}, {"question": "Who was Josie?", "answer": "Deputy U.S. Marshal Josie Wells, 27, of Harleston, Mississippi. He was killed in the line of duty on March 10, 2015."}]'::jsonb,
   'https://www.youtube.com/watch?v=-Ik2-1rP5rA'),
  ('Justin',
   'justin',
   'hero',
   null,
   'For Time',
   '30-20-10 For Time',
   '20–35 min',
   'advanced',
   'full-body',
   array['barbell','pullUpBar']::text[],
   'time',
   'Justin honors U.S. Marine Corps Sgt. Justin M. Hansen, 26, of Traverse City, Michigan, assigned to the 2nd Marine Special Operations Battalion at Camp Lejeune, North Carolina. He died on July 24, 2012, in Badghis Province, Afghanistan, while conducting combat operations.

You do 30, 20 and 10 reps of back squats, bench presses and strict pull-ups. The back squat and bench press are both done at your own bodyweight, so you need a squat rack and a bench. That is 60 reps of each movement. Heavy squats and bench presses for high reps are rare in a timed workout, and strict pull-ups give you no help from a kip.',
   '[{"name": "Back Squats", "reps": "30-20-10", "tip": "Squat below parallel with your chest up. Use a rack with safety arms.", "rx_men": "Bodyweight", "rx_women": "Bodyweight"}, {"name": "Bench Press", "reps": "30-20-10", "tip": "Touch your chest and lock out every rep. Use a spotter or safety arms.", "rx_men": "Bodyweight", "rx_women": "Bodyweight"}, {"name": "Strict Pull-Ups", "reps": "30-20-10", "tip": "No kip. Start from a dead hang and pull until your chin clears the bar."}]'::jsonb,
   'Record your finish time.',
   '["Set up the rack, bench and pull-up bar close together", "Break the 30s into small sets from the start", "Never bench heavy without a spotter or safety arms"]'::jsonb,
   '["Load the barbell to your bodyweight rounded to the nearest plates, and note the load with your time.", "If you have one barbell, set up the squat rack so you can move it to the bench quickly, or use two bars.", "Break the 30 back squats into sets of 5 to 10 and rack the bar before your form slips.", "On the bench press, keep your feet planted and shoulder blades pulled back.", "Strict pull-ups fail fast, so take sets of 3 to 5 with short rests."]'::jsonb,
   'Lower the squat and bench to half or three quarters of your bodyweight. Use banded pull-ups, jumping pull-ups or ring rows. Newer athletes can do 15-10-5.',
   '[{"question": "What is the Justin workout?", "answer": "30-20-10 reps for time of back squats, bench presses and strict pull-ups. The back squat and bench press are at bodyweight."}, {"question": "How many total reps are in Justin?", "answer": "180 reps: 60 back squats, 60 bench presses and 60 strict pull-ups."}, {"question": "What weight do I use for Justin?", "answer": "Your own bodyweight on the barbell for both the back squat and the bench press."}, {"question": "Who was Justin?", "answer": "U.S. Marine Corps Sgt. Justin M. Hansen, 26, of Traverse City, Michigan, of the 2nd Marine Special Operations Battalion. He died on July 24, 2012, in Badghis Province, Afghanistan."}]'::jsonb,
   'https://www.youtube.com/watch?v=pxbGV0glJSw'),
  ('K27',
   'k27',
   'hero',
   null,
   'For Time',
   '27 Rounds For Time',
   '35–55 min',
   'advanced',
   'full-body',
   array['barbell','jumpRope','bodyweight']::text[],
   'time',
   'K27 honors Sgt. Greg Moore, 43, of the Coeur d''Alene Police Department in Idaho, who died in the line of duty on May 5, 2015. While patrolling an area hit by car break-ins, he was shot after stopping a suspicious person. He served for 14 years and was a member of Lotus CrossFit.

You complete 27 rounds of 5 hang power cleans (185 lb / 105 lb), 5 burpees and 15 double-unders. Each round is short, but 27 of them add up to 135 cleans, 135 burpees and 405 double-unders. The men''s load is heavy for 135 reps, so grip and back fatigue build round after round.',
   '[{"name": "Hang Power Cleans", "reps": "5", "tip": "Start at mid-thigh, drive your hips and catch the bar above parallel. Singles are fine at this load.", "rx_men": "185 lb", "rx_women": "105 lb"}, {"name": "Burpees", "reps": "5", "tip": "Chest to the floor and a small jump at the top. Step back up if it saves your legs."}, {"name": "Double-Unders", "reps": "15", "tip": "Relaxed shoulders and quick wrists. Keep your jumps small."}]'::jsonb,
   'Record your finish time.',
   '["Find a pace you can hold for all 27 rounds", "Keep the bar, rope and burpee spot close together", "Count rounds with chalk marks or a counter"]'::jsonb,
   '["Decide early how you will do the cleans, such as 5 quick singles, and keep the same plan every round.", "Drop the bar from the hang only if you can catch your breath, then reset with a flat back.", "Let your arms stay long on the burpees so your grip gets a short rest.", "If you miss on the double-unders, take one breath before you start again rather than rushing.", "Use a whiteboard or counter so you do not lose track of rounds."]'::jsonb,
   'Lower the barbell to 135 lb / 75 lb or less. Do 30 single-unders instead of 15 double-unders. Cut the workout to 15 rounds if 27 is too long for you.',
   '[{"question": "What is the K27 workout?", "answer": "27 rounds for time of 5 hang power cleans (185 lb / 105 lb), 5 burpees and 15 double-unders."}, {"question": "How many total reps are in K27?", "answer": "675 reps: 135 hang power cleans, 135 burpees and 405 double-unders."}, {"question": "Who does K27 honor?", "answer": "Sgt. Greg Moore, 43, of the Coeur d''Alene Police Department in Idaho. He died in the line of duty on May 5, 2015."}, {"question": "Can I scale the rounds?", "answer": "Yes. Keep the round the same and do fewer rounds, such as 15, then note the change with your time."}]'::jsonb,
   null),
  ('Kelly Brown',
   'kelly-brown',
   'hero',
   null,
   'For Time',
   '5 Rounds For Time',
   '20–30 min',
   'advanced',
   'full-body',
   array['rower','box','barbell','wallBall']::text[],
   'time',
   'Kelly Brown honors CrossFit Kids Seminar Staff Flowmaster Kelly Brown, who died on Sept. 15, 2020, at 44, after a five-year battle with ovarian cancer. She and her husband started CrossFit in 2006, opened CrossFit Agoge in 2007, and she joined the CrossFit Kids Seminar Staff in 2010.

You complete 5 rounds of a 440 m row, 10 box jumps (30 in / 24 in), 10 deadlifts (275 lb / 185 lb) and 10 wall-ball shots (30 lb ball to 10 ft / 20 lb ball to 9 ft). The heavy deadlifts and the heavy ball make this harder than it looks. Your legs get no break, because the row, the box, the deadlift and the wall ball all lean on them.',
   '[{"name": "Row", "reps": "440 m", "tip": "Drive with your legs first, then lean back and pull. Hold a pace you can repeat 5 times."}, {"name": "Box Jumps", "reps": "10", "tip": "Land softly with your whole foot on the box and stand tall. Step down to save your legs.", "rx_men": "30 in", "rx_women": "24 in"}, {"name": "Deadlifts", "reps": "10", "tip": "Flat back, bar close to your legs. Break the set before your back rounds.", "rx_men": "275 lb", "rx_women": "185 lb"}, {"name": "Wall Balls", "reps": "10", "tip": "Full squat and hit the target on every rep. The ball is heavy, so use your legs to throw it.", "rx_men": "30 lb to 10 ft", "rx_women": "20 lb to 9 ft"}]'::jsonb,
   'Record your finish time.',
   '["Row at a pace you can repeat for 5 rounds", "Break the deadlifts early", "The ball is heavier than usual, so plan your sets"]'::jsonb,
   '["Hold the same split on the rower each round so your legs are ready for the box.", "Step down from the box rather than rebounding, to save your legs and Achilles.", "Plan the deadlifts as 5 and 5, or 4, 3 and 3, from the first round.", "On the wall balls, catch the ball high and sink straight into the next squat.", "Set the box, barbell and target close to the rower so the switches are quick."]'::jsonb,
   'Lower the box to 24 in / 20 in, the deadlift to 185 lb / 125 lb, and use a 20 lb / 14 lb ball. Step-ups can replace box jumps. Newer athletes can do 3 rounds.',
   '[{"question": "What is the Kelly Brown workout?", "answer": "5 rounds for time of a 440 m row, 10 box jumps (30 in / 24 in), 10 deadlifts (275 lb / 185 lb) and 10 wall-ball shots (30 lb ball to 10 ft / 20 lb ball to 9 ft)."}, {"question": "How many total reps are in Kelly Brown?", "answer": "150 reps: 50 box jumps, 50 deadlifts and 50 wall-ball shots, plus 2,200 m of rowing."}, {"question": "Is the ball really 30 lb?", "answer": "Yes. CrossFit lists a 30 lb ball to 10 ft for men and a 20 lb ball to 9 ft for women, heavier than the usual 20 lb / 14 lb."}, {"question": "Who was Kelly Brown?", "answer": "A CrossFit Kids Seminar Staff Flowmaster and the co-owner of CrossFit Agoge. She died on Sept. 15, 2020, at 44, after a five-year battle with ovarian cancer."}]'::jsonb,
   'https://www.youtube.com/watch?v=iKWaREoFHNU'),
  ('Kerrie',
   'kerrie',
   'hero',
   null,
   'For Time',
   '10 Rounds For Time',
   '45–65 min',
   'advanced',
   'full-body',
   array['running','weightedVest','bodyweight']::text[],
   'time',
   'Kerrie honors Kerrie Orozco, 29, a seven-year veteran of the Omaha Police Department, who was killed in the line of duty on May 20, 2015, hours before she was set to start maternity leave. She began CrossFit at CrossFit FitFarm and volunteered with the Special Olympics.

You wear a weight vest for 10 rounds of a 100 m sprint, 5 burpees, 20 sit-ups, 15 push-ups and another 100 m sprint, with 2 minutes of rest in each round. That adds up to 2,000 m of sprinting, 50 burpees, 200 sit-ups and 150 push-ups. CrossFit does not give a vest weight, so choose one and note it. The rest helps, but the push-ups and sprints add up round after round.',
   '[{"name": "100m Sprint", "reps": "100 m", "tip": "Fast but controlled. Build speed over the first few steps."}, {"name": "Burpees", "reps": "5", "tip": "Chest to the floor and a small jump at the top."}, {"name": "Sit-Ups", "reps": "20", "tip": "Touch the floor behind your head and your feet at the top. Use an AbMat if you have one."}, {"name": "Push-Ups", "reps": "15", "tip": "Chest to the floor and lock out at the top. Break into small sets early."}, {"name": "100m Sprint", "reps": "100 m", "tip": "Sprint again, then start your rest as soon as you cross the line."}, {"name": "Rest", "reps": "2 min", "isRest": true, "tip": "Walk and breathe. Start the next round on time."}]'::jsonb,
   'Record your finish time. CrossFit does not say whether to rest after the 10th round, so note whether your time includes it.',
   '["Pick a vest weight you can sprint in", "Use the 2-minute rest to recover, not to stand still", "Break the push-ups before you fail"]'::jsonb,
   '["Strap the vest tight and high so it does not bounce on the sprints.", "Treat the sprints as fast strides in the early rounds and push harder in the last few.", "Split the 15 push-ups into sets such as 8 and 7 from the first round.", "Breathe out as you sit up and keep a steady rhythm on the sit-ups.", "Use a running clock so you know when each 2-minute rest ends."]'::jsonb,
   'Do it without a vest or with a light one. Do push-ups from your knees or with your hands on a box. Cut the workout to 5 rounds, or halve the sit-ups and push-ups.',
   '[{"question": "What is the Kerrie workout?", "answer": "10 rounds for time of a 100 m sprint, 5 burpees, 20 sit-ups, 15 push-ups, a 100 m sprint and 2 minutes of rest, wearing a weight vest."}, {"question": "How many total reps are in Kerrie?", "answer": "400 reps: 50 burpees, 200 sit-ups and 150 push-ups, plus 2,000 m of sprinting."}, {"question": "How heavy should the vest be?", "answer": "CrossFit only says to wear a weight vest and does not give a weight. Choose one you can sprint in and note it with your time."}, {"question": "Who was Kerrie?", "answer": "Kerrie Orozco, 29, a seven-year veteran of the Omaha Police Department. She was killed in the line of duty on May 20, 2015."}]'::jsonb,
   'https://www.youtube.com/watch?v=7Ro_-uJItcA'),
  ('Kev',
   'kev',
   'hero',
   null,
   'AMRAP 26',
   'AMRAP 26 (Partner)',
   '26 min',
   'advanced',
   'full-body',
   array['barbell','pullUpBar']::text[],
   'rounds_reps',
   'Kev honors Operator Cpl. Kevin van de Rijdt, 26, of the Netherlands, a member of Special Forces (Korps Commando Troepen) Task Force 55. He died on Sept. 6, 2009, during heavy combat in Afghanistan. He was a CrossFit athlete and instructor in Venlo, and his favorite movements were deadlifts, bar muscle-ups and partner bar-facing burpees.

With a partner, you complete as many rounds as you can in 26 minutes of 6 deadlifts each (315 lb / 205 lb), 9 synchronized bar-facing burpees, 9 bar muscle-ups each and a 55 ft partner barbell carry. The deadlifts are heavy and the muscle-ups demand skill, so grip and breathing set the pace for most rounds.',
   '[{"name": "Deadlifts", "reps": "6 each", "tip": "Flat back, bar close to your legs. Take singles at this load.", "rx_men": "315 lb", "rx_women": "205 lb"}, {"name": "Synchronized Bar-Facing Burpees", "reps": "9", "tip": "Both partners hit the floor and jump the bar at the same time. Call the count out loud."}, {"name": "Bar Muscle-Ups", "reps": "9 each", "tip": "Kip hard, pull the bar to your hips and press out at the top. Small sets keep you moving."}, {"name": "Partner Barbell Carry", "reps": "55 ft", "tip": "Carry the loaded barbell together. Agree on your grip before you lift it.", "rx_men": "315 lb", "rx_women": "205 lb"}]'::jsonb,
   'Score is total rounds + reps for the team.',
   '["Take the heavy deadlifts as singles", "Talk through the synchronized burpees", "Agree on how you will carry the bar before you start"]'::jsonb,
   '["Let one partner deadlift while the other rests, and swap after each rep or after each set of 6.", "On the synchronized burpees, the faster partner waits so you both jump the bar together.", "Break the bar muscle-ups into sets of 2 or 3 before you start missing.", "Set the bar down under control at the end of the carry, with both of you lowering it together.", "Plan your route for the 55 ft carry so you can turn around without stopping."]'::jsonb,
   'Lower the barbell to 225 lb / 155 lb or less for the deadlifts and the carry. Replace bar muscle-ups with chest-to-bar pull-ups, pull-ups or jumping muscle-ups. Use regular burpees if the bar-facing jump is too much.',
   '[{"question": "What is the Kev workout?", "answer": "With a partner, as many rounds and reps as possible in 26 minutes of 6 deadlifts each, 9 synchronized bar-facing burpees, 9 bar muscle-ups each and a 55 ft partner barbell carry. The barbell is 315 lb / 205 lb."}, {"question": "How many reps are in one round of Kev?", "answer": "39 reps for the team: 12 deadlifts, 9 synchronized burpees and 18 bar muscle-ups, plus the 55 ft carry."}, {"question": "How do you carry the barbell with a partner?", "answer": "CrossFit does not say how to hold the bar for the partner carry. Both partners carry the one barbell, so agree on a grip that is safe for you both and keep it the same each time you repeat the workout."}, {"question": "Who was Kev?", "answer": "Operator Cpl. Kevin van de Rijdt, 26, of the Netherlands Special Forces (Korps Commando Troepen). He died on Sept. 6, 2009, during heavy combat in Afghanistan."}]'::jsonb,
   'https://www.youtube.com/watch?v=qCsUiHlUHoc'),
  ('Kevin',
   'kevin',
   'hero',
   null,
   'For Time',
   '3 Rounds For Time',
   '25–40 min',
   'intermediate',
   'full-body',
   array['barbell','pullUpBar','dumbbells','running']::text[],
   'time',
   'Kevin honors Navy Special Warfare Operator 1st Class Kevin Ebbert, 32, of Arcata, California, assigned to an East Coast-based Naval Special Warfare unit in Virginia Beach, Virginia. He died on Nov. 24, 2012, in Uruzgan Province, Afghanistan, while supporting combat stability operations.

You complete 3 rounds of 32 deadlifts (185 lb / 125 lb), 32 hanging hip touches with alternating arms, and an 800 m running farmers carry with 15 lb / 10 lb dumbbells. The deadlifts and the bar work both draw on your grip, and then you have to hold the dumbbells for a half-mile run. The light dumbbells feel heavier every round.',
   '[{"name": "Deadlifts", "reps": "32", "tip": "Flat back, bar close to your legs. Break into sets such as 12, 10 and 10.", "rx_men": "185 lb", "rx_women": "125 lb"}, {"name": "Hanging Hip Touches", "reps": "32", "tip": "Hang from the bar, pull and turn so one hip comes up to the bar, then switch sides. CrossFit''s page has no written standard, so follow its demo video."}, {"name": "Farmers Carry", "reps": "800 m", "tip": "Run while holding a dumbbell in each hand. Keep your shoulders back and arms straight.", "rx_men": "15 lb dumbbells", "rx_women": "10 lb dumbbells"}]'::jsonb,
   'Record your finish time.',
   '["Break the deadlifts early to save your grip", "Count the hip touches as 16 per side", "Run the carry at a pace you can hold"]'::jsonb,
   '["Use a hook grip or switch to a mixed grip on the deadlifts if your hands start to open.", "On the hip touches, keep your arms straight and drive with your hips and core.", "Watch CrossFit''s hanging hip touch demo before you start, because the page does not write out a standard.", "Hold the dumbbells loosely at your sides on the run and let your arms hang straight.", "Set the dumbbells by the door so you can start the carry the moment you leave the bar."]'::jsonb,
   'Lower the barbell to 135 lb / 95 lb or less. Replace the hip touches with hanging knee raises or knees-to-elbows. Shorten the carry to 400 m, or run without dumbbells if your grip is the limit.',
   '[{"question": "What is the Kevin workout?", "answer": "3 rounds for time of 32 deadlifts (185 lb / 125 lb), 32 hanging hip touches with alternating arms, and an 800 m running farmers carry with 15 lb / 10 lb dumbbells."}, {"question": "How many total reps are in Kevin?", "answer": "192 reps: 96 deadlifts and 96 hanging hip touches, plus 2,400 m of running with dumbbells."}, {"question": "What is a hanging hip touch?", "answer": "You hang from the bar, then pull and turn so one hip comes up to touch the bar, switching sides each rep. CrossFit''s workout page does not write out the standard, but CrossFit has a demo video of the movement."}, {"question": "Who was Kevin?", "answer": "Navy Special Warfare Operator 1st Class Kevin Ebbert, 32, of Arcata, California. He died on Nov. 24, 2012, in Uruzgan Province, Afghanistan."}]'::jsonb,
